local function add(ctx,self)local p=ctx:controller(self);ctx:grant_player_keyword(p,"cthun_buffs");ctx:increment_player_data(p,"cthun_attack_buff",2);ctx:increment_player_data(p,"cthun_health_buff",2);for _,id in ipairs(ctx:minions_died(p))do if id=="OG_280"then ctx:shuffle_card_into_deck(p,"OG_280");break end end end
return {api_version=1,id="OG_255",name="Doomcaller",text="<b>Battlecry:</b> Give your C'Thun +2/+2 <i>(wherever it is).</i> If it's dead, shuffle it into your deck.",set="OG",type="minion",rarity="rare",cost=8,attack=7,health=9,keywords={"battlecry"},on_battlecry=add}
